// 동기화(beta) — 같은 Tailscale tailnet 위 다른 기기(휴대폰 브라우저, 또 다른 데스크톱)가 이 PC 의
// Brise 에 붙는 임베디드 HTTP 서버(axum). 웹 클라이언트(/app)를 서빙하고, /api/v1/* 로 읽기·쓰기
// (POST /api/v1/invoke 가 http:true 커맨드 전체를 연다)와 실시간 변경 통지(SSE)를 제공한다 —
// 라우트 구성은 handlers.rs 헤더 참고. 지금 모델은 "PC 가 서버, 다른 기기는 /app 클라이언트"이고
// 양방향 LWW 동기화(docs/SYNC.md Phase 2)는 아직 없다.
//
// AppState(commands/mod.rs)에는 필드를 추가하지 않는다 — 서버 핸들은 별도 SyncState 로
// app.manage() 한다(lib.rs 참고).
pub mod bind;
// Generated by scripts/gen-commands.mjs from specs/commands/*.yaml (http:true commands only) —
// see dispatch.gen.rs header. #[path] because the .gen.rs suffix mirrors src/lib/commands.gen.ts's
// naming convention rather than the plain `dispatch.rs` Rust's default module resolution expects.
#[path = "dispatch.gen.rs"]
pub(crate) mod dispatch;
/// HTTP 라우트 계층(ServerState · build_router) — 라우트별 구현은 handlers/ 아래. handlers.rs 헤더 참고.
pub(crate) mod handlers;
/// 캡처 ingest 리스너(크롬 익스텐션 클리핑) — 같은 axum 인프라를 쓰지만 sync 서버와는 완전히
/// 독립된 별개 서버다(127.0.0.1 고정, 자체 포트/토큰). ingest.rs 헤더 주석 참고.
pub mod ingest;

use crate::error::{io as ioerr, AppResult};
use rusqlite::Connection;
use std::net::SocketAddr;
use std::path::{Path, PathBuf};

pub struct Running {
    pub handle: tauri::async_runtime::JoinHandle<()>,
    pub addr: SocketAddr,
    pub token: String,
}

/// 앱 전역 서버 핸들. Default라 lib.rs::setup() 이 boot autostart 보다 먼저 관리해 둘 수 있다
/// (맨 처음엔 None — 아직 안 켜짐).
#[derive(Default)]
pub struct SyncState(pub parking_lot::Mutex<Option<Running>>);

const DEFAULT_PORT: i64 = 7332;

fn read_sync_settings(conn: &Connection) -> AppResult<(bool, u16, String)> {
    let settings = crate::repo::settings::get_all(conn)?;
    let enabled = settings.get("sync_enabled").and_then(|v| v.as_bool()).unwrap_or(false);
    let port = settings.get("sync_port").and_then(|v| v.as_i64()).unwrap_or(DEFAULT_PORT) as u16;
    let token = settings.get("sync_token").and_then(|v| v.as_str()).unwrap_or("").to_string();
    Ok((enabled, port, token))
}

/// 서버 시작 — 바인딩 주소는 bind::pick_bind_addr 가 강제한다(Tailscale CGNAT 우선, 없으면
/// loopback, 절대 0.0.0.0 아님). data_dir/port/token 만으로 완전히 결정되는 순수 함수형 시작점이라
/// AppState 없이도 임시 디렉토리 + 포트 0(OS가 빈 포트 배정)으로 통합 테스트를 돌릴 수 있다.
pub fn start(
    data_dir: PathBuf,
    port: u16,
    token: String,
    app_handle: Option<tauri::AppHandle>,
) -> AppResult<(SocketAddr, tauri::async_runtime::JoinHandle<()>)> {
    let ip = bind::pick_bind_addr(&bind::local_ipv4_addrs());
    // U7(AUDIT-2026-09-26-fallback-observability.md §4/§6): Tailscale CGNAT 인터페이스가 없어
    // loopback으로 폴백했다는 사실은 예전엔 아무 데도 남지 않았다(다른 기기에서 동기화 서버에
    // 붙지 못하는 이유를 사용자가 알 길이 없었다). bind::pick_bind_addr는 순수 함수로 남기고
    // (기존 유닛 테스트가 후보 목록만으로 검증한다), 유일한 호출자인 여기서 판정한다. 테스트가
    // port 0으로 이 함수를 직접 부를 때도 매번 loopback이라 디듀프(60초)가 반복 소음을 눌러준다.
    if ip == std::net::IpAddr::V4(std::net::Ipv4Addr::LOCALHOST) {
        crate::diag::warn(
            "sync",
            "bind_loopback",
            "no Tailscale CGNAT interface found, binding to loopback only",
        );
    }
    let addr = SocketAddr::new(ip, port);
    let std_listener = std::net::TcpListener::bind(addr).map_err(ioerr)?;
    std_listener.set_nonblocking(true).map_err(ioerr)?;
    let bound_addr = std_listener.local_addr().map_err(ioerr)?;
    // SSE fan-out (GET /api/v1/events) subscribes to the process-wide crate::events bus, not to a
    // channel owned by this server — that is what lets a desktop IPC write (which never touches
    // this module) reach the phone.
    let sse_subscribers = std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(0));
    let (shutdown_tx, shutdown) = tokio::sync::watch::channel(());
    let router = handlers::build_router(handlers::ServerState {
        data_dir,
        token,
        app_handle,
        sse_subscribers,
        shutdown,
        ai_rate_limiter: std::sync::Arc::new(handlers::AiRateLimiter::new()),
    });
    let handle = tauri::async_runtime::spawn(async move {
        let _shutdown_tx = shutdown_tx; // abort 로 이 future 가 drop 되면 열린 SSE 가 끝난다(handlers::ServerState::shutdown)
        // tokio::net::TcpListener::from_std 는 현재 스레드에 활성 Tokio reactor(Handle::current())가
        // 있어야 한다 — setup() 은 그 컨텍스트 밖에서 동기 실행되므로, 변환 자체를 스폰된 async
        // 블록 안으로 옮겨서 여기(타우리 런타임 위)에서 수행한다.
        let listener = match tokio::net::TcpListener::from_std(std_listener) {
            Ok(l) => l,
            Err(e) => {
                // U7: serve-task death — 이 async 블록이 여기서 return하면 동기화 서버는
                // 다시 뜨지 않는다(수동으로 껐다 켜기 전까지). diag가 유일한 흔적이다.
                crate::diag::error("sync", "listener_setup_failed", format!("{e}"));
                return;
            }
        };
        if let Err(e) = axum::serve(listener, router).await {
            // Serve errors can embed peer/request detail on some platforms — never echo a raw
            // query string that may carry ?token= (handlers::redact_token_in_text).
            crate::diag::error(
                "sync",
                "serve_failed",
                handlers::redact_token_in_text(&e.to_string()),
            );
        }
    });
    Ok((bound_addr, handle))
}

/// 실행 중이면 중단(abort). 설정 토글-off/토큰 재발급 시 호출 — no-op이면 조용히 지나간다.
pub fn stop(state: &SyncState) {
    if let Some(running) = state.0.lock().take() {
        running.handle.abort();
    }
}

/// 부팅 시 sync_enabled=true 면 자동 기동. lib.rs::setup() 이 db::maybe_spawn_auto_backup 옆에서
/// 호출한다 — 그 함수와 동일한 이유로 bootstrap() 안이 아니라 여기 별도 진입점이다(테스트가
/// tempdir에 반복 bootstrap() 하는데, 그때마다 서버가 뜨면 안 된다). 토큰이 아직 없으면(설정
/// 화면에서 한 번도 켠 적 없음) 시작하지 않는다 — authorized() 의 fail-closed 규칙과 대칭.
pub fn maybe_start_at_boot(app: &tauri::AppHandle, conn: &Connection, data_dir: &Path) {
    use tauri::Manager;
    let (enabled, port, token) = match read_sync_settings(conn) {
        Ok(v) => v,
        Err(e) => {
            crate::diag::error("sync", "boot_settings_read_failed", format!("{e}"));
            return;
        }
    };
    if !enabled || token.is_empty() {
        return;
    }
    match start(data_dir.to_path_buf(), port, token.clone(), Some(app.clone())) {
        Ok((addr, handle)) => {
            let sync_state = app.state::<SyncState>();
            *sync_state.0.lock() = Some(Running { handle, addr, token });
        }
        Err(e) => crate::diag::error("sync", "boot_autostart_failed", format!("{e}")),
    }
}

